    """
    Sorts input list descending, finds the largest prime, 
    and returns the sum of its digits.
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    def sum_digits(n):
        return sum(int(d) for d in str(abs(n)))

    return next(
        (sum_digits(n) for n in sorted(numbers, reverse=True) if is_prime(n)),
        0
    )

