def check_triple(a: float, b: float, c: float) -> bool:
    """Return True if any two of a, b, c satisfy the Pythagorean relation."""
    squares = (a * a, b * b, c * c)
    return (
        squares[0] + squares[1] == squares[2] or
        squares[0] + squares[2] == squares[1] or
        squares[1] + squares[2] == squares[0]
    )
