def _to_number(x):
    """Convert a string with commas to a float, or return the number as is."""
    if isinstance(x, str):
        x = x.replace(',', '.')
        try:
            return float(x)
        except ValueError:
            # If conversion fails, return the original string
            return x
    return x

def compare(a, b):
    a_num = _to_number(a)
    b_num = _to_number(b)

    # If both are numbers (int/float) or can be compared as numbers
    try:
        if a_num == b_num:
            return None
        return a_num if a_num > b_num else b_num
    except TypeError:
        # If they are not comparable, raise an error
        raise TypeError("Both arguments must be comparable numbers or numeric strings.")
